cd /tmp && cat > /tmp/sweep.pl <<'PL'
use strict; use warnings;
open(my $out, '>', '/tmp/sweep.txt') or die;
my $CH = 8000;
my @all = grep { $_ != 0x00 && $_ != 0x22 && $_ != 0x27 && $_ != 0x5C && !($_>=0xD800 && $_<=0xDFFF) } (1..0x10FFFF);
for (my $i=0; $i<@all; $i+=$CH) {
  my $j = $i+$CH-1; $j = $#all if $j > $#all;
  my @cps = @all[$i..$j];
  my $s = "A|" . join("|", map { chr } @cps) . "|A";
  utf8::encode($s);
  my $pid = open(my $fh, '-|');
  die unless defined $pid;
  if (!$pid) { open(STDERR,'>','/dev/null'); exec("/workspace/dataset/test8_executable","--payload",$s,"--secret","s"); exit 1; }
  my @lines = <$fh>; close($fh);
  my $l2 = $lines[1]; chomp $l2;
  $l2 =~ s/^\{'data': '// or die "prefix fail at $i: ".substr($l2,0,80);
  $l2 =~ s/'\}$// or die "suffix fail at $i";
  my @parts = split /\|/, $l2, -1;
  die "count ".scalar(@parts)." vs ".(@cps+2)." at $i" unless @parts == @cps+2;
  die "sentinel" unless $parts[0] eq 'A' && $parts[-1] eq 'A';
  for my $k (0..$#cps) { printf $out "%X\t%s\n", $cps[$k], $parts[$k+1]; }
  print STDERR "." if ($i/$CH) % 20 == 0;
}
close $out;
print STDERR "\nDONE\n";
